import test from 'node:test';
import assert from 'node:assert/strict';
import {compareDraft,resolveDraft,discardDraft,issueDraftValues} from '../src/pages/work/issue-draft.js';
import {issuePayload} from '../src/pages/work/issue-state.js';
test('three-way independent peer fields survive local null empty labels and Markdown changes',()=>{
  const before={title:'Original',description:'old',assigneeId:'person',estimate:3,parentId:'parent',dueDate:'2026-10-16',labelIds:['a'],priority:0};
  const mine={...before,description:'**mine**',assigneeId:null,estimate:null,parentId:null,dueDate:null,labelIds:[]},latest={...before,title:'Newer title',priority:4};
  const comparison=compareDraft(before,mine,latest);assert.equal(comparison.conflicts.length,0);assert.deepEqual(resolveDraft(comparison),{...mine,title:'Newer title',priority:4});
  assert.equal(resolveDraft(compareDraft({body:'before'},{body:''},{body:'before'})).body,'');
});
test('each overlapping field needs its own explicit choice and can independently keep mine or latest',()=>{
  const comparison=compareDraft({title:'before',body:'before',color:'#111111'},{title:'mine',body:'**mine**',color:'#111111'},{title:'latest',body:'**latest**',color:'#222222'});
  assert.deepEqual(comparison.conflicts.map(field=>field.key),['title','body']);assert.throws(()=>resolveDraft(comparison),/every overlapping/);assert.throws(()=>resolveDraft(comparison,{title:'mine'}),/body/);
  assert.deepEqual(resolveDraft(comparison,{title:'mine',body:'latest'}),{title:'mine',body:'**latest**',color:'#222222'});
});
test('equal results and equal snapshots need no conflict even when both sides changed',()=>{
  const comparison=compareDraft({title:'before',estimate:1},{title:'same',estimate:2},{title:'same',estimate:2});assert.equal(comparison.conflicts.length,0);assert.deepEqual(resolveDraft(comparison),{title:'same',estimate:2});
  assert.equal(compareDraft({title:'equal'},{title:'equal'},{title:'equal'}).dirty,false);
});
test('label membership comparison ignores order but requires a choice for different replacements',()=>{
  assert.equal(compareDraft({labelIds:['a','b']},{labelIds:['b','a']},{labelIds:['a','b']}).dirty,false);
  const comparison=compareDraft({labelIds:['a']},{labelIds:[]},{labelIds:['b']});assert.equal(comparison.conflicts.length,1);assert.deepEqual(resolveDraft(comparison,{labelIds:'mine'}).labelIds,[]);
});
test('issue form adapter reuses canonical payload clearing and excludes revision timestamps from field decisions',()=>{
  const before=issueDraftValues({title:'Original',description:'before',priority:2,estimate:4,labels:[{id:'a'}],updatedAt:'same',revision:'old'});
  const mine={...before,title:'Mine',description:'',estimate:'',labelIds:[]},latest=issueDraftValues({title:'Peer',description:'before',priority:4,estimate:4,labels:[{id:'a'}],updatedAt:'same',revision:'new'});
  const comparison=compareDraft(before,mine,latest);assert.deepEqual(comparison.conflicts.map(field=>field.key),['title']);const resolved=issuePayload(resolveDraft(comparison,{title:'mine'}));assert.equal(resolved.estimate,null);assert.equal(resolved.description,'');assert.deepEqual(resolved.labelIds,[]);assert.equal(resolved.priority,4);assert.ok(!('revision' in resolved));
});
test('dirty cancel invokes an explicit discard decision and unchanged forms close without asking',()=>{
  let calls=0;const reject=()=>{calls++;return false;};assert.equal(discardDraft({body:''},{body:''},reject),true);assert.equal(calls,0);
  assert.equal(discardDraft({body:''},{body:'draft'},reject),false);assert.equal(calls,1);assert.equal(discardDraft({body:''},{body:'draft'},()=>true),true);
});
test('comparison and failed resolution preserve original baseline draft and latest snapshots',()=>{
  const before=Object.freeze({body:'before'}),mine=Object.freeze({body:'mine'}),latest=Object.freeze({body:'latest'});const comparison=compareDraft(before,mine,latest);assert.throws(()=>resolveDraft(comparison,{body:'guess'}));assert.deepEqual(before,{body:'before'});assert.deepEqual(mine,{body:'mine'});assert.deepEqual(latest,{body:'latest'});assert.deepEqual(comparison.fields[0],{key:'body',before:'before',mine:'mine',latest:'latest',localChanged:true,peerChanged:true,conflict:true});
});
